	store := NewStore(30 * time.Minute)
	http.HandleFunc("/session", sessionHandler(store))
	http.HandleFunc("/healthz", healthHandler(store))
	addr, err := resolveListenAddr()
	if err != nil {
		log.Fatal(err)
	}
	log.Printf("listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, nil))
}

// resolveListenAddr reads deploy/service.conf and returns the configured
// listen address. It falls back to :8080 if the key is absent.
func resolveListenAddr() (string, error) {
	f, err := os.Open(filepath.Join("deploy", "service.conf"))
	if err != nil {
		return "", err
	}
	defer f.Close()

	scanner := bufio.NewScanner(f)
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		key, value, ok := strings.Cut(line, "=")
		if !ok || strings.TrimSpace(key) != "listen_address" {
			continue
		}
		if addr := strings.TrimSpace(value); addr != "" {
			return addr, nil
		}
	}
	if err := scanner.Err(); err != nil {
		return "", err
	}
	return "", fmt.Errorf("listen_address not found in %s", filepath.Join("deploy", "service.conf"))
}

